"""Read-only audit of active CSVs. Writes findings, never library data."""
from pathlib import Path
import csv,hashlib,math,json
root=Path(__file__).resolve().parents[1]
read=lambda name:list(csv.DictReader((root/name).open(encoding='utf-8-sig',newline='')))
materials=read('assets/library/materials.csv');sections=read('assets/library/sections.csv')
original={name:hashlib.sha256((root/'assets/library'/name).read_bytes()).hexdigest() for name in ['materials.csv','sections.csv']}
rows=[];differences=[];checks=0
def compare(record,expected,source):
 global checks
 errors=[]
 for key,value in expected.items():
  checks+=1
  actual=float(record[key]) if record.get(key) else None
  if actual is None or not math.isclose(actual,value,rel_tol=1e-8,abs_tol=1e-6):
   item=dict(id=record['id'],field=key,csv=actual,reference=value,source=source);differences.append(item);errors.append(key)
 rows.append(dict(id=record['id'],status='DISCREPANCY' if errors else 'MATCH (checked fields)',fields=list(expected),source=source))
 return errors
sources={
 'sawn':'https://napier-repository.worktribe.com/OutputFile/2762670',
 'glulam':'https://www.swedishwood.com/siteassets/5-publikationer/pdfer/glulamhandbook2-240508.pdf',
 'ipe':'https://www.britishsteel.co.uk/wp-content/uploads/2025/08/british-steel-european-sections-product-range.pdf',
 'concrete':'https://www.phd.eng.br/wp-content/uploads/2015/12/en.1992.1.1.2004.pdf',
 'steel':'https://www.phd.eng.br/wp-content/uploads/2015/12/en.1993.1.1.2005.pdf',
 'lvl':'https://www.metsagroup.com/contentassets/f8ff384a208d4786959efa4bca9fab2c/kerto_lvl_for_load-bearing_applications.pdf',
 'osb':'https://www.egger.com/get_download/29ccb859-7689-4757-bb93-b5f6a3edb992/Brochure_OSB_3_Francais.pdf'}
# Columns transcribed independently from the cited tables, not generated by runtime library code.
sawn={
 'C14':[14,7.2,16,2,3,7000,4700,230,440,290,350],
 'C16':[16,8.5,17,2.2,3.2,8000,5400,270,500,310,370],
 'C18':[18,10,18,2.2,3.4,9000,6000,300,560,320,380],
 'C20':[20,11.5,19,2.3,3.6,9500,6400,320,590,330,400],
 'C22':[22,13,20,2.4,3.8,10000,6700,330,630,340,410],
 'C24':[24,14.5,21,2.5,4,11000,7400,370,690,350,420],
 'C27':[27,16.5,22,2.5,4,11500,7700,380,720,360,430],
 'C30':[30,19,24,2.7,4,12000,8000,400,750,380,460],
 'C35':[35,22.5,25,2.7,4,13000,8700,430,810,390,470],
 'C40':[40,26,27,2.8,4,14000,9400,470,880,400,480]}
glulam={
 'GL20h':[20,16,20,8400,7000,340,370], 'GL22h':[22,17.6,22,10500,8800,370,410],
 'GL24h':[24,19.2,24,11500,9600,385,420], 'GL26h':[26,20.8,26,12100,10100,405,445],
 'GL28h':[28,22.4,28,12600,10500,425,460], 'GL30h':[30,24,30,13600,11300,430,480],
 'GL32h':[32,25.6,32,14200,11800,440,490], 'GL24c':[24,17,21.5,11000,9100,365,400],
 'GL28c':[28,19.5,24,12500,10400,390,420], 'GL30c':[30,19.5,24.5,13000,10800,390,430],
 'GL32c':[32,19.5,24.5,13500,11200,400,440]}
for m in materials:
 mid=m['id'];family=m['family']
 if mid in sawn:
  expected=dict(zip(['fm_k','ft0_k','fc0_k','fc90_k','fv_k','E0_mean','E0_05','E90_mean','G_mean','rho_k','rho_mean'],sawn[mid]));expected['ft90_k']=.4;compare(m,expected,sources['sawn'])
 elif mid in glulam:
  expected=dict(zip(['fm_k','ft0_k','fc0_k','E0_mean','E0_05','rho_k','rho_mean'],glulam[mid]));expected.update(ft90_k=.5,fc90_k=2.5,fv_k=3.5,E90_mean=300,G_mean=650,G_05=540,Gr_mean=65);compare(m,expected,sources['glulam'])
 elif family=='Concrete':
  fck,_cube_label=map(int,mid[1:].split('/'));grade=[12,16,20,25,30,35,40,45,50,55,60,70,80,90].index(fck);E=[27,29,30,31,33,34,35,36,37,38,39,41,42,44][grade]*1000;cube=[15,20,25,30,37,45,50,55,60,67,75,85,95,105][grade]
  fcm=fck+8;fct=.3*fck**(2/3) if fck<=50 else 2.12*math.log(1+fcm/10)
  expected=dict(fck=fck,fck_cube=cube,fcm=fcm,E=E,Ecm=E,G=E/2.4,nu=.2,fctm=fct,fctk_005=.7*fct,fctk_095=1.3*fct,Ecm_formula=22000*(fcm/10)**.3)
  expected.update(epsilon_c1=min(.7*fcm**.31,2.8),epsilon_cu1=3.5 if fck<=50 else 2.8+27*((98-fcm)/100)**4,epsilon_c2=2 if fck<=50 else 2+.085*(fck-50)**.53,epsilon_cu2=3.5 if fck<=50 else 2.6+35*((90-fck)/100)**4,n=2 if fck<=50 else 1.4+23.4*((90-fck)/100)**4,epsilon_c3=1.75 if fck<=50 else 1.75+.55*(fck-50)/40,epsilon_cu3=3.5 if fck<=50 else 2.6+35*((90-fck)/100)**4)
  compare(m,expected,sources['concrete'])
 elif family=='Steel':compare(m,dict(E=210000,G=210000/2.6,density=7850),sources['steel'])
 elif mid=='Kerto-S':compare(m,dict(fm_k=44,fm_flat_k=50,ft0_k=35,ft90_k=.8,fc0_k=35,fc90_k=6,fc90_flat_k=2.2,fv_k=4.2,fv_flat_k=2.3,E0_mean=13800,G_mean=600,rho_k=480,rho_mean=510),sources['lvl'])
 elif mid=='Kerto-Q':
  compare(m,dict(fm_k=32,fm_flat_k=36,ft0_k=26,ft90_k=6,fc0_k=26,fc90_k=9,fc90_flat_k=2.2,fv_k=4.5,fv_flat_k=1.3,E0_mean=10500,E90_mean=2000,G_mean=600,rho_k=480,rho_mean=510),sources['lvl']+' (27–75 mm group)')
 elif mid.startswith('OSB3-'):
  expected=dict(zip(['fm_k','ft0_k','ft90_k','fc0_k','fc90_k'],[16.4,9.4,7,15.4,12.7] if mid.endswith('18') else [14.8,9,6.8,14.8,12.4]));expected.update(fv_k=6.8,fr_k=1,E0_mean=3800,E90_mean=3000,Em_flat=4930,G_mean=1080,Gr_mean=50,rho_k=550);compare(m,expected,sources['osb'])
 else:rows.append(dict(id=mid,status='NOT EXTERNALLY VERIFIED',fields=[],source='Product ETA/DoP or project specification required. Generic CLT, template or user-reference record.'))
# All 11 active IPE catalogue rows, converted from published cm/dm units.
sizes=[160,180,200,220,240,270,300,400,450,500,600]
dims=[[82,5,7.4,9,869,68],[91,5.3,8,9,1317,101],[100,5.6,8.5,12,1943,142],[110,5.9,9.2,12,2772,205],[120,6.2,9.8,15,3892,284],[135,6.6,10.2,15,5790,420],[150,7.1,10.7,15,8356,604],[180,8.6,13.5,20,23015,1317],[190,9.4,14.6,20,33597,1675],[200,10.2,16,20,48017,2141],[220,12,19,20,90952,3384]]
props=[[109,17,124,26,.004,3.54,20.1,15.8],[146,22,166,35,.0075,4.73,23.9,18.8],[194,28,221,45,.0131,6.92,28.5,22.4],[252,37,285,58,.0228,9.03,33.4,26.2],[324,47,367,74,.0376,13,39.1,30.7],[429,62,484,97,.0708,15.9,45.9,36.1],[557,81,628,125,.126,19.9,53.8,42.2],[1151,146,1301,228,.492,49.7,84.1,66.3],[1493,176,1695,276,.794,65,98.5,77.6],[1921,214,2186,335,1.25,87.1,115,90.7],[3032,308,3471,483,2.86,154,154,122]]
original_sizes={s['id']:s for s in read('assets/reference-en1995/sections.csv')}
for sec in sections:
 if sec['family']=='IPE':
  i=sizes.index(int(sec['h']));B,tw,tf,r,Iy,Iz=dims[i];Wy,Wz,Wpy,Wpz,Iw,J,A,mass=props[i]
  compare(sec,dict(h=sizes[i],b=B,tw=tw,tf=tf,r=r,Iy=Iy*10000,Iz=Iz*10000,Wy=Wy*1000,Wz=Wz*1000,Wply=Wpy*1000,Wplz=Wpz*1000,Iw=Iw*1e12,J=J*10000,A=A*100,mass=mass),sources['ipe'])
 else:
  original_row=original_sizes.get(sec['id']);compare(sec,dict(b=float(original_row['b']),h=float(original_row['h'])),'Supplied EN1995 trade-size reference. Dimensions are presets, not Eurocode-mandated sizes.')
for name,digest in original.items():assert hashlib.sha256((root/'assets/library'/name).read_bytes()).hexdigest()==digest
report=['# Database audit — 22 October 2026','',f'{len(materials)} material records and {len(sections)} section records reviewed; {checks} numerical field comparisons. Existing CSVs were not edited.','',f'**{len(differences)} discrepancies require review.** A MATCH covers only the listed fields; it does not certify an unspecified product or national application.','', '## Discrepancies — no changes made','','| Record | Field | CSV | Reference |','|---|---|---:|---:|']
for d in differences:report.append(f"| {d['id']} | {d['field']} | {d['csv']} | {d['reference']} |")
report+=['','GL28h has a source discrepancy; confirm the applicable EN 14080 edition/product before choosing a correction. Kerto-S transverse compression differs from the current manufacturer table. Kerto-Q mixes thickness/orientation groups; select the intended product and thickness before correcting it. These strength fields do not run resistance checks. Kerto-Q longitudinal E also affects deflection.','','## Record-by-record coverage','','| Record | Status | Numerical fields checked |','|---|---|---:|']
for row in rows:report.append(f"| {row['id']} | {row['status']} | {len(row['fields'])} |")
report+=['','## Qualification','','Five generic/template/user-reference materials lack a uniquely matching external specification (CLT-C24, CLT-T14, Plywood-template, Spano-V313-18, Cement-board-12). No blanket correctness claim is made. OSB mean density is an assumption; published characteristic density was compared. Derived G_05 for sawn timber and convenience aliases are not independent standard declarations. Steel presets do not include design strengths. Concrete density 2400 kg/m³ remains an editable assumption. Concrete E uses rounded table values while other equation fields retain unrounded values.','','The 26 timber/LVL section dimensions match the supplied source; geometry is independently checked by integration tests. The 11 IPE rows match the cited British Steel edition and its rounding. Other manufacturers/catalogues may differ. Warping/torsion units were checked; engineering approximations for custom geometry are not exact 3D stress solutions.','','## Sources','']
for name,url in sources.items():report.append(f'- [{name}]({url})')
report+=['','## Unchanged CSV fingerprints','']+[f'- {name}: `{digest}`' for name,digest in original.items()]
(root/'DATA-AUDIT.md').write_text('\n'.join(report)+'\n',encoding='utf-8')
(root/'tests/data-audit-results.json').write_text(json.dumps(dict(checks=checks,records=rows,discrepancies=differences,hashes=original),indent=2)+'\n',encoding='utf-8')
print(f'{checks} numeric comparisons; {len(rows)} records; {len(differences)} discrepancies; CSV hashes unchanged. Details in DATA-AUDIT.md')
